fn ae_identity(v:&Value)->Option<(u8,u64)>{match v{Value::Record(r)=>Some((0,r.borrow().id)),Value::Seq(r)=>Some((1,r.borrow().id)),Value::Result(r)=>Some((2,r.borrow().id)),_=>None}}
