macro_rules! ae_seq {($ty:expr,[$($value:expr),*])=>{ae_seq($ty,vec![$($value),*])}}
macro_rules! ae_map {($ctx:expr,$seq:expr,$f:ident)=>{{let items=ae_items($seq);let mut out=vec![];for x in items{$ctx.tick();out.push($f($ctx,vec![x]));}ae_sequence(out)}}}
macro_rules! ae_fold {($ctx:expr,$seq:expr,$initial:expr,$f:ident)=>{{let items=ae_items($seq);let mut out=$initial;for x in items{$ctx.tick();out=$f($ctx,vec![out,x]);}out}}}
macro_rules! ae_match {($value:expr,$ok:ident,$ok_body:expr,$err:ident,$err_body:expr)=>{{let result=$value;let (variant,value)=if let Value::Result(r)=result{let row=r.borrow();(row.variant.clone(),row.value.clone())}else{panic!("result_type")};if variant=="ok"{let $ok=value;$ok_body}else{let $err=value;$err_body}}}}
pub fn ae_json(v:&Value)->String{fn encode(v:&Value,seen:&mut HashSet<u64>)->J{match v{Value::Closure(c)=>return serde_json::json!({"tag":"closure","id":c.id.to_string(),"capabilities":c.meta["capabilities"]}),Value::Task(t)=>return serde_json::json!({"tag":"task","id":t.borrow().id.to_string(),"state":(["pending","running","completed"][t.borrow().state as usize])}),_=>{}}if let Some((_,id))=ae_identity(v){if !seen.insert(id){return serde_json::json!({"tag":"ref","id":id.to_string()})}return match v{Value::Record(r)=>serde_json::json!({"tag":"record","id":id.to_string(),"fields":r.borrow().fields.iter().map(|(k,x)|serde_json::json!([k,encode(x,seen)])).collect::<Vec<_>>()}),Value::Seq(r)=>serde_json::json!({"tag":"sequence","id":id.to_string(),"items":r.borrow().items.iter().map(|x|encode(x,seen)).collect::<Vec<_>>()}),Value::Result(r)=>serde_json::json!({"tag":"result","id":id.to_string(),"variant":r.borrow().variant,"value":encode(&r.borrow().value,seen)}),_=>unreachable!()};}match v{Value::Unit=>serde_json::json!({"tag":"null"}),Value::Int(n)=>serde_json::json!({"tag":"int","value":n.to_string()}),Value::Bool(b)=>serde_json::json!({"tag":"bool","value":b}),Value::Str(s)=>serde_json::json!({"tag":"string","value":s}),_=>unreachable!()}}encode(v,&mut HashSet::new()).to_string()}

#[derive(Debug)]pub struct AeClosure{pub id:u64,pub meta:J,pub captures:Vec<Value>,pub body:fn(&mut Context,&[Value],&[Value])->Value}
#[derive(Debug)]pub struct AeTask{pub id:u64,pub ty:J,pub caps:Vec<String>,pub captures:Vec<Value>,pub body:fn(&mut Context,&[Value],&[Value])->Value,pub state:u8,pub result:Value}
fn ae_type_equal(a:&J,b:&J)->bool{fn norm(v:&J,key:&str)->J{match v{J::Array(xs)=>{let mut values:Vec<J>=xs.iter().map(|x|norm(x,"")).collect();if key=="capabilities"{values.sort_by_key(|v|v.as_str().unwrap().to_string());}J::Array(values)},J::Object(xs)=>J::Object(xs.iter().map(|(k,v)|(k.clone(),norm(v,k))).collect()),_=>v.clone()}}norm(a,"")==norm(b,"")}
fn ae_executable_check(t:&J,v:&Value){if t["t"]=="Fn"{let c=if let Value::Closure(c)=v{c}else{panic!("closure_type")};let actual=serde_json::json!({"t":"Fn","params":c.meta["params"].as_array().unwrap().iter().map(|p|p["ty"].clone()).collect::<Vec<_>>(),"returns":c.meta["returns"],"capabilities":c.meta["capabilities"]});if !ae_type_equal(t,&actual){panic!("closure_type")}}else{let task=if let Value::Task(t)=v{t}else{panic!("task_type")};if !ae_type_equal(t,&task.borrow().ty){panic!("task_type")}}}
fn ae_host_allowed(ctx:&Context,cap:&str)->bool{(ctx.policy)(cap)&&ctx.grants.iter().any(|c|c==cap)}
fn ae_authority(ctx:&Context,caps:&[String]){if caps.iter().any(|c|!ae_host_allowed(ctx,c)||!ctx.frames.last().is_some_and(|f|f.contains(c))){panic!("capability_denied")}}
pub fn ae_capture(values:&[Value],index:&str)->Value{let i:usize=index.parse().expect("capture_index");if i.to_string()!=index{panic!("capture_index")}values.get(i).expect("capture_index").clone()}
pub fn ae_arg(values:&[Value],index:&str)->Value{ae_capture(values,index)}
pub fn ae_lambda(ctx:&mut Context,text:&str,symbols:&[&str],captures:Vec<Value>,body:fn(&mut Context,&[Value],&[Value])->Value)->Value{let meta:J=serde_json::from_str(text).unwrap();let caps:Vec<String>=meta["capabilities"].as_array().unwrap().iter().map(|c|c.as_str().unwrap().to_string()).collect();if symbols.len()!=captures.len(){panic!("capture_shape")}ae_authority(ctx,&caps);Value::Closure(Rc::new(AeClosure{id:ae_id(),meta,captures,body}))}
pub fn ae_apply(ctx:&mut Context,value:Value,args:Vec<Value>)->Value{let c=if let Value::Closure(c)=value{c}else{panic!("closure_type")};let caps:Vec<String>=c.meta["capabilities"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().to_string()).collect();ae_authority(ctx,&caps);let types:Vec<J>=c.meta["params"].as_array().unwrap().iter().map(|p|p["ty"].clone()).collect();ae_arguments(&serde_json::to_string(&types).unwrap(),&args);let borrowed:Vec<&str>=caps.iter().map(String::as_str).collect();let result=ctx.function(&borrowed,|ctx|ae_bind(&c.meta["returns"].to_string(),(c.body)(ctx,&c.captures,&args)));ae_authority(ctx,&caps);result}
pub fn ae_spawn(ctx:&mut Context,text:&str,symbols:&[&str],captures:Vec<Value>,body:fn(&mut Context,&[Value],&[Value])->Value)->Value{let ty:J=serde_json::from_str(text).unwrap();let caps=ctx.frames.last().expect("task_frame").clone();if ty["t"]!="Task"||symbols.len()!=captures.len(){panic!("task_shape")}ae_authority(ctx,&caps);Value::Task(Rc::new(RefCell::new(AeTask{id:ae_id(),ty,caps,captures,body,state:0,result:Value::Unit})))}
pub fn ae_await(ctx:&mut Context,value:Value)->Value{let task=if let Value::Task(t)=value{t}else{panic!("task_type")};let(ty,caps,captures,body,state,result)={let t=task.borrow();(t.ty.clone(),t.caps.clone(),t.captures.clone(),t.body,t.state,t.result.clone())};ae_authority(ctx,&caps);if state==2{return result}if state==1{panic!("task_cycle")}task.borrow_mut().state=1;let borrowed:Vec<&str>=caps.iter().map(String::as_str).collect();let outcome=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||ctx.function(&borrowed,|ctx|ae_bind(&ty["result"].to_string(),body(ctx,&captures,&[])))));match outcome{Ok(v)=>{{let mut t=task.borrow_mut();t.state=2;t.result=v.clone();}ae_authority(ctx,&caps);v},Err(e)=>{task.borrow_mut().state=0;std::panic::resume_unwind(e)}}}
macro_rules! ae_lambda {($ctx:expr,$meta:expr,[$($symbol:expr),*],[$($v:expr),*],$c:ident,$captured:ident,$args:ident,$body:expr)=>{{let captured=vec![$($v),*];ae_lambda($ctx,$meta,&[$($symbol),*],captured,|$c,$captured,$args|$body)}}}
macro_rules! ae_spawn {($ctx:expr,$meta:expr,[$($symbol:expr),*],[$($v:expr),*],$c:ident,$captured:ident,$args:ident,$body:expr)=>{{let captured=vec![$($v),*];ae_spawn($ctx,$meta,&[$($symbol),*],captured,|$c,$captured,$args|$body)}}}
macro_rules! ae_apply {($ctx:expr,$value:expr,[$($arg:expr),*])=>{{let value=$value;let args=vec![$($arg),*];ae_apply($ctx,value,args)}}}
macro_rules! ae_await {($ctx:expr,$value:expr)=>{{let value=$value;ae_await($ctx,value)}}}
fn ae_effect_values(values:&[Value]){fn check(v:&Value,seen:&mut HashSet<usize>){match v{Value::Closure(_)|Value::Task(_)=>panic!("opaque_effect_value"),Value::Record(r)=>{let row=r.borrow();if !seen.insert(Rc::as_ptr(r) as usize){return}for(_,x)in &row.fields{check(x,seen);}},Value::Seq(s)=>{let row=s.borrow();if !seen.insert(Rc::as_ptr(s) as usize){return}for x in &row.items{check(x,seen);}},Value::Result(r)=>{let row=r.borrow();if seen.insert(Rc::as_ptr(r) as usize){check(&row.value,seen);}},_=>{}}}let mut seen=HashSet::new();for value in values{check(value,&mut seen);}}

#[cfg(panic="abort")] compile_error!("Aether Atomic requires Rust panic=unwind");
thread_local! {
 static AE_TRANSACTIONS:RefCell<Vec<Vec<AeUndo>>>=RefCell::new(vec![]);
 static AE_RECYCLED_RECORDS:RefCell<Vec<Rc<RefCell<AeRecord>>>>=RefCell::new(vec![]);
}
enum AeUndo {Write(Rc<RefCell<AeRecord>>,String,Value),Allocate(Rc<RefCell<AeRecord>>)}
fn ae_undo(undo:AeUndo){AE_TRANSACTIONS.with(|stack|{if let Some(frame)=stack.borrow_mut().last_mut(){frame.push(undo)}});}
pub struct AeAtomic {depth:usize,steps:usize,restore:Rc<std::cell::Cell<Option<usize>>>}
pub fn ae_atomic(ctx:&mut Context)->AeAtomic {let depth=AE_TRANSACTIONS.with(|s|{let mut s=s.borrow_mut();s.push(vec![]);s.len()});AeAtomic{depth,steps:ctx.steps,restore:ctx.atomic_restore.clone()}}
impl Drop for AeAtomic {fn drop(&mut self){let undo=AE_TRANSACTIONS.with(|s|{let mut s=s.borrow_mut();assert_eq!(s.len(),self.depth,"atomic_order");s.pop().unwrap()});if std::thread::panicking(){for item in undo.into_iter().rev(){match item{AeUndo::Write(record,name,value)=>{record.borrow_mut().fields.iter_mut().find(|(k,_)|k==&name).unwrap().1=value;},AeUndo::Allocate(record)=>{let mut r=record.borrow_mut();r.live=false;r.fields.clear();drop(r);AE_RECYCLED_RECORDS.with(|s|s.borrow_mut().push(record));}}}self.restore.set(Some(self.steps));}else{AE_TRANSACTIONS.with(|s|{if let Some(parent)=s.borrow_mut().last_mut(){parent.extend(undo)}});}}}
fn ae_allocate_record(ty:J,fields:Vec<(String,Value)>)->Value {let record=AE_RECYCLED_RECORDS.with(|s|s.borrow_mut().pop()).unwrap_or_else(||Rc::new(RefCell::new(AeRecord{ty:J::Null,fields:vec![],id:ae_id(),frozen:false,live:true})));{let mut r=record.borrow_mut();r.ty=ty;r.fields=fields;r.live=true;r.frozen=false;}ae_undo(AeUndo::Allocate(record.clone()));Value::Record(record)}
fn ae_record_write(record:&Rc<RefCell<AeRecord>>,name:&str){let value=record.borrow().fields.iter().find(|(k,_)|k==name).unwrap().1.clone();ae_undo(AeUndo::Write(record.clone(),name.to_string(),value));}
